import z3
print("z3 version:", z3.get_version_string())

# Let's try to solve using z3
n = 22

# Create boolean variables for each edge
edge_vars = {}
for i in range(n):
    for j in range(i+1, n):
        edge_vars[(i,j)] = z3.Bool(f"e_{i}_{j}")

print(f"Number of variables: {len(edge_vars)}")

# For each 5-set, add constraints
solver = z3.Solver()

# Count 5-sets
from itertools import combinations
five_sets = list(combinations(range(n), 5))
print(f"Number of 5-sets: {len(five_sets)}")

# Add constraints
for subset in five_sets:
    edges = []
    for i in range(5):
        for j in range(i+1, 5):
            a, b = subset[i], subset[j]
            if a < b:
                edges.append(edge_vars[(a,b)])
            else:
                edges.append(edge_vars[(b,a)])
    # Not all red: at least one edge is blue (False)
    solver.add(z3.Or([z3.Not(v) for v in edges]))
    # Not all blue: at least one edge is red (True)
    solver.add(z3.Or(edges))

print("Constraints added. Solving...")
result = solver.check()
print(f"Result: {result}")

if result == z3.sat:
    model = solver.model()
    colors = []
    for i in range(n):
        for j in range(i+1, n):
            val = model.evaluate(edge_vars[(i,j)])
            colors.append(1 if z3.is_true(val) else 0)
    print(f"Solution length: {len(colors)}")
    print(f"First 30: {colors[:30]}")

    # Verify
    from itertools import combinations
    for subset in combinations(range(n), 5):
        all_red = True
        all_blue = True
        for i in range(5):
            for j in range(i+1, 5):
                a, b = subset[i], subset[j]
                if a < b:
                    idx = (a * (2*n - a - 1)) // 2 + (b - a - 1)
                else:
                    idx = (b * (2*n - b - 1)) // 2 + (a - b - 1)
                if colors[idx] == 0:
                    all_red = False
                if colors[idx] == 1:
                    all_blue = False
        if all_red:
            print(f"ERROR: Red clique found: {subset}")
        if all_blue:
            print(f"ERROR: Blue clique found: {subset}")
    print("Verification complete")
else:
    print("UNSAT")

